{"content":"using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// The console entry point: builds the same host graph <see cref="Program"/> uses and returns the
/// hosted service's exit code. Tests call this directly with their own writers to exercise the
/// full production path (host → hosted service → runner → classifier).
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>
	/// Runs the CLI. <paramref name="output"/> / <paramref name="error"/> default to
	/// <see cref="Console.Out"/> / <see cref="Console.Error"/>.
	/// </summary>
	public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null, CancellationToken cancellationToken = default)
	{
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		var host = builder.Build();

		// Resolve BEFORE RunAsync(): RunAsync disposes the provider on shutdown.
		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync(cancellationToken).ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
