{"content":"using System.Text.Json;
using System.Text.Json.Serialization;

namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// One HoldoutGate trace line, as written by <c>tools/LetUsCook.HoldoutGate</c> (camelCase JSONL).
/// Only the fields the census reads are mapped; unknown fields are ignored.
/// </summary>
public sealed record TraceLine
{
	/// <summary>The raw recipe line as written.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>The holdout row id (e.g. <c>debug:recipe-slug</c>).</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>The line's index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>The trace set: <c>debug</c> or <c>batch</c>; anything else is refused (D-029).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Whether the line shipped to the household without review.</summary>
	public bool Auto { get; init; }

	/// <summary>Whether the line landed on the labelled (key) row.</summary>
	public bool Correct { get; init; }

	/// <summary>The labelled (key) descriptions; <c>[0]</c> is the key row.</summary>
	public IReadOnlyList<string> ExpectedDescriptions { get; init; } = [];

	/// <summary>The labelled (key) data types; <c>[0]</c> is the key row's tier.</summary>
	public IReadOnlyList<string> ExpectedDataTypes { get; init; } = [];

	/// <summary>The accepted descriptions; <c>[0]</c> is the accepted row.</summary>
	public IReadOnlyList<string> ActualDescriptions { get; init; } = [];

	/// <summary>The accepted data types; <c>[0]</c> is the accepted row's tier.</summary>
	public IReadOnlyList<string> ActualDataTypes { get; init; } = [];

	/// <summary>The resolver atoms for the line.</summary>
	public IReadOnlyList<TraceAtom> Atoms { get; init; } = [];
}

/// <summary>One resolver atom of a trace line.</summary>
public sealed record TraceAtom
{
	/// <summary>The atom text handed to the resolver.</summary>
	public string Text { get; init; } = string.Empty;

	/// <summary><c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	public string Outcome { get; init; } = string.Empty;

	/// <summary>The decision path: <c>ranker</c>, <c>override</c>, or <c>curated</c>.</summary>
	public string Path { get; init; } = string.Empty;

	/// <summary>Whether the accepted row was a reuse of an existing ingredient master.</summary>
	public bool Reused { get; init; }

	/// <summary>The linked ingredient master slug, when one was linked.</summary>
	public string? LinkedIngredientId { get; init; }

	/// <summary>The parsed ingredient name.</summary>
	public string ParsedName { get; init; } = string.Empty;
}

/// <summary>
/// JSON options for the trace records: web defaults (camelCase, case-insensitive) match the
/// HoldoutGate trace writer.
/// </summary>
[JsonConverter(typeof(TraceLineJsonConverter))]
public sealed class TraceLineJson
{
	/// <summary>Deserializes one trace line from a JSONL record.</summary>
	/// <param name="json">The JSON object text.</param>
	/// <returns>The trace line.</returns>
	public static TraceLine Parse(string json)
	{
		return JsonSerializer.Deserialize<TraceLine>(json, TraceLineJson.Options)
			?? throw new JsonException("trace line deserialized to null");
	}

	/// <summary>The shared deserializer options.</summary>
	public static class TraceLineJson
	{
		/// <summary>Web defaults: camelCase, case-insensitive, unknown fields ignored.</summary>
		public static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);
	}
}
