{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row vs the key row <b>relation</b>
/// and the decision <b>site</b> — using the production helpers (F-428 P12.13, D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the labelled row is empty.</summary>
	public const string NoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, the key row is Canned, the accepted row is not.</summary>
	public const string PackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name is only its first word.</summary>
	public const string CompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: the head terms agree and the state masks differ.</summary>
	public const string StateMismatch = "state-mismatch";

	/// <summary>Relation: head and state agree and the dataset tiers differ.</summary>
	public const string RowChoiceTier = "row-choice-tier";

	/// <summary>Relation: head, state and tier agree; only the qualifiers differ.</summary>
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string SiblingFood = "sibling-food";

	/// <summary>Relation: no rule held, or a field a rule needed was missing.</summary>
	public const string Other = "other";

	/// <summary>Site: the line reused an existing row via the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the exact-override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker path without reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reused single-token list for the per-token state checks: ExtractCandidateState/
	// ExtractCandidateSatisfiers take IReadOnlyList, and the classifier is single-threaded.
	private readonly List<string> _singleToken = [];

	/// <summary>Creates a classifier over the production normalizer and the exact-override key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The exact-override key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Classifies one auto-wrong line. The first relation that holds wins, in the brief's order:
	/// no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier,
	/// same-head-other-qualifier, sibling-food, other.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
		var acceptedHeadParsed = FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
		var keyHead = SingularPhrase(keyHeadParsed.HeadTerm);
		var acceptedHead = SingularPhrase(acceptedHeadParsed.HeadTerm);
		var parsedName = SingularPhrase(atom?.ParsedName ?? string.Empty);
		var keyPhrase = KeyHeadPhrase(keyTokens);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		result.Site = ClassifySite(atom, line.RawText);
		if (result.Site == SiteOverride)
		{
			result.OverrideKey = _overrideKeys.IsKey(FoldForOverrideKey(line.RawText)) ? "yes" : "no";
		}

		result.Relation = ClassifyRelation(
			line.RawText,
			keyDesc,
			acceptedDesc,
			keyTier,
			acceptedTier,
			keyState,
			acceptedState,
			keyHead,
			acceptedHead,
			parsedName,
			keyPhrase,
			keyHeadParsed,
			acceptedHeadParsed,
			result);

		return result;
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to the first token the
	/// production state/modifier vocabulary marks as non-head (a <c>ModifierWords</c> member, or a
	/// token <see cref="FdcMatcher.ExtractCandidateState"/>/<see cref="FdcMatcher.ExtractCandidateSatisfiers"/>
	/// reports a state for). "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>;
	/// "Tomatoes, crushed, canned" → <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens, in order.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);
		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifier(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/>
	/// ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/> — the same composition the matcher feeds
	/// to <c>StateAgrees</c> (FdcMatcher.cs:1155-1157).
	/// </summary>
	/// <param name="tokens">A normalized token list.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>Whether the production rule reuses that master for this name.</returns>
	public static bool ShouldReuseParsedName(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	private string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private string ClassifyRelation(
		string rawText,
		string keyDesc,
		string acceptedDesc,
		string keyTier,
		string acceptedTier,
		FoodState keyState,
		FoodState acceptedState,
		IReadOnlyList<string> keyHead,
		IReadOnlyList<string> acceptedHead,
		IReadOnlyList<string> parsedName,
		IReadOnlyList<string> keyPhrase,
		ParsedFdcDescription keyHeadParsed,
		ParsedFdcDescription acceptedHeadParsed,
		ClassificationResult result)
	{
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return NoLabel;
		}

		if (PackUnitRegex().IsMatch(rawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			return PackUnitState;
		}

		if (keyPhrase.Count >= 2
			&& parsedName.Count == 1
			&& string.Equals(parsedName[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return CompoundHeadLost;
		}

		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);
		if (!headsAgree)
		{
			return SiblingFood;
		}

		if (keyState != acceptedState)
		{
			return StateMismatch;
		}

		if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
		{
			result.MissingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
			return Other;
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return RowChoiceTier;
		}

		var keyQualifiers = SingularPhraseList(keyHeadParsed.Qualifiers);
		var acceptedQualifiers = SingularPhraseList(acceptedHeadParsed.Qualifiers);
		var keyOnly = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
		var acceptedOnly = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.Ordinal).ToArray();
		result.KeyOnlyQualifiers = keyOnly;
		result.AcceptedOnlyQualifiers = acceptedOnly;
		return SameHeadOtherQualifier;
	}

	private bool IsStateOrModifier(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleToken.Clear();
		_singleToken.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>
	/// Folds a raw line text for the exact-override key lookup: lower-cased, trimmed, and content from
	/// the first <c>(</c> dropped — the same fold <c>FdcMatcher.MatchAsync</c> applies before its
	/// raw-key lookup (FdcMatcher.cs:165; <c>StripFromParenthesis</c> is private, so the fold is
	/// reproduced here and the key set is the production file's).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded key candidate.</returns>
	public static string FoldForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
#pragma warning disable CA1308 // Reason: parity with FdcMatcher.MatchAsync's lower-cased override lookup.
		var lowered = rawText.Trim().ToLowerInvariant();
#pragma warning restore CA1308
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? lowered[..paren] : lowered).Trim();
	}
}
