{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes — the accepted row vs the key row <b>relation</b>
/// and the decision <b>site</b> — using the production helpers (F-428 P12.13, D-014):
/// <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/>,
/// <see cref="IngredientLineResolver.SingularizeToken"/> and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary><c>no-label</c>: the line has no labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary><c>pack-unit-state</c>: a can/jar unit line whose key row is Canned and the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary><c>compound-head-lost</c>: the key head phrase is two or more words and the parsed name is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary><c>state-mismatch</c>: the head terms agree and the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary><c>row-choice-tier</c>: head and state agree and the dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary><c>same-head-other-qualifier</c>: head, state and tier agree; only the qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary><c>sibling-food</c>: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary><c>other</c>: no relation check held, or a field the check needs is missing from the trace.</summary>
	public const string RelationOther = "other";

	/// <summary><c>reuse</c>: ranker path, row reused from an existing master.</summary>
	public const string SiteReuse = "reuse";

	/// <summary><c>override</c>: the shortcut override path.</summary>
	public const string SiteOverride = "override";

	/// <summary><c>curated</c>: the curated catalogue path.</summary>
	public const string SiteCurated = "curated";

	/// <summary><c>ranker</c>: ranker path, no reuse.</summary>
	public const string SiteRanker = "ranker";

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Single-element scratch for the per-token state probes: the classifier is used single-threaded by the runner.
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Creates a classifier over the production normalizer and the exact-overrides key set.</summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The <c>exact-overrides.json</c> raw-key set.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		_normalizer = normalizer ?? throw new ArgumentNullException(nameof(normalizer));
		_overrideKeys = overrideKeys ?? throw new ArgumentNullException(nameof(overrideKeys));
	}

	/// <summary>
	/// Classifies one auto-wrong line. The relation checks run in the brief's order — the first that
	/// holds wins; the site comes from the atom's decision path.
	/// </summary>
	/// <param name="line">The trace line (<c>auto == true && correct == false</c>).</param>
	/// <returns>The classification; <see cref="ClassificationResult.Site"/> is empty when the atom path is unknown.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);

		var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();

		var parsedName = atom?.ParsedName ?? string.Empty;
		var site = ClassifySite(atom, line.RawText);

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var parsedNameTokens = SingularPhrase(parsedName);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var relation = RelationOther;
		string? missingField = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = RelationPackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = RelationCompoundHeadLost;
		}
		else if (keyHeadPhrase.Count == 0)
		{
			relation = RelationOther;
			missingField = "expectedDescriptions";
		}
		else if (HeadsAgree(keyHead, acceptedHead))
		{
			if (keyState != acceptedState)
			{
				relation = RelationStateMismatch;
			}
			else if (string.IsNullOrWhiteSpace(keyTier) || string.IsNullOrWhiteSpace(acceptedTier))
			{
				relation = RelationOther;
				missingField = string.IsNullOrWhiteSpace(keyTier) ? "expectedDataTypes" : "actualDataTypes";
			}
			else if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
			{
				relation = RelationRowChoiceTier;
			}
			else
			{
				relation = RelationSameHeadOtherQualifier;
			}
		}
		else
		{
			relation = RelationSiblingFood;
		}

		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;
		if (relation == RelationSameHeadOtherQualifier)
		{
			var keyQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
			var acceptedQualifiers = SingularPhraseList(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
			keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
			acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).OrderBy(t => t, StringComparer.OrdinalIgnoreCase).ToArray();
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.IsKey(NormalizeForOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = parsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key head phrase: the key description's normalized tokens up to (excluding) the first token
	/// the production state/modifier vocabulary marks as state — the food-identity words, singularised.
	/// "Bread, crumbs, dry, grated, plain" → <c>bread crumbs</c>; "Tomatoes, crushed, canned" → <c>tomato</c>.
	/// </summary>
	/// <param name="keyTokens">The key description's normalized tokens.</param>
	/// <returns>The head phrase tokens, singularised.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);

		var phrase = new List<string>(keyTokens.Count);
		foreach (var token in keyTokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule (<see cref="IngredientLineResolver.ShouldReuse"/>)
	/// would link <paramref name="parsedName"/> to <paramref name="linkedIngredientId"/>.
	/// </summary>
	/// <param name="parsedName">The parser name.</param>
	/// <param name="linkedIngredientId">The linked master slug.</param>
	/// <returns>Whether the production reuse rule holds for the pair.</returns>
	public bool ReuseRuleHolds(string parsedName, string linkedIngredientId) =>
		IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(parsedName), linkedIngredientId);

	/// <summary>The dataset tier of a trace dataType string; <see cref="FdcDataset.None"/> when unparseable.</summary>
	/// <param name="dataType">The trace dataType string.</param>
	/// <returns>The tier.</returns>
	public static FdcDataset DatasetOf(string? dataType) =>
		Enum.TryParse<FdcDataset>(dataType, ignoreCase: true, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>The production state mask for a token list: <see cref="FdcMatcher.ExtractCandidateState"/> ∪ <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>.</summary>
	/// <param name="tokens">The normalized tokens.</param>
	/// <returns>The combined mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Folds a raw line text the way the override lookup does: lower-cased, trimmed, content from the first <c>(</c> dropped.</summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		var text = rawText.Trim();
		var paren = text.IndexOf('(', StringComparison.Ordinal);
		if (paren >= 0)
		{
			text = text[..paren];
		}

#pragma warning disable CA1308 // Reason: parity with FdcMatcher's override-lookup folding.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private static string First(IReadOnlyList<string> values)
	{
		for (var i = 0; i < values.Count; i++)
		{
			if (!string.IsNullOrWhiteSpace(values[i]))
			{
				return values[i];
			}
		}

		return string.Empty;
	}

	private static bool HeadsAgree(IReadOnlyList<string> keyHead, IReadOnlyList<string> acceptedHead) =>
		keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

	private static string ClassifySite(TraceAtom? atom, string rawText)
	{
		if (atom is null)
		{
			return string.Empty;
		}

		return atom.Path switch
		{
			"ranker" when atom.Reused => SiteReuse,
			"ranker" => SiteRanker,
			"override" => SiteOverride,
			"curated" => SiteCurated,
			_ => string.Empty,
		};
	}

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();
}
