{"content":"using System.Globalization;
using System.Text;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one census or pairs invocation: reads the trace, refuses any set other than debug/batch
/// (D-029), classifies every <c>auto &amp;&amp; !correct</c> line, writes the TSV to the output
/// sink and the relation × site summary to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunner runner,
	AutoWrongCensusOptions options,
	AutoWrongClassifier classifier,
	IAutoWrongCensusOutput output)
{
	/// <summary>Trace sets the census may read; anything else is refused (D-029).</summary>
	public static readonly FrozenSet<string> AllowedSets = FrozenSet.ToFrozenSet(["debug", "batch"], StringComparer.Ordinal);

	/// <summary>TSV column order — the CLI contract (brief §4).</summary>
	public const string TsvHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	/// <summary>Runs the invocation and returns the exit code.</summary>
	/// <param name="cancellationToken">Cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or a malformed invocation.</returns>
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		_ = runner;

		if (string.IsNullOrEmpty(options.Command))
		{
			output.Error.WriteLine("unusable arguments; expected: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(options.TracePath))
		{
			output.Error.WriteLine($"trace file not found: {options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(options.TracePath, output, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Select(l => l.Set).Where(s => !AllowedSets.Contains(s)).Distinct().ToArray();
		if (refused.Length > 0)
		{
			output.Error.WriteLine($"refused: trace set '{string.Join("', '", refused)}' is not debug or batch (D-029)");
			return 1;
		}

		return options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines, output)
			: RunPairs(options.CensusTsvPath, lines, output);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines, IAutoWrongCensusOutput output)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToArray();
		var results = new List<ClassificationResult>(autoWrong.Length);
		var unknownSites = 0;

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSites++;
				output.Error.WriteLine($"unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' for {line.HoldoutId}#{line.LineIndex}; not classified");
				continue;
			}

			results.Add(result);
		}

		output.Output.WriteLine(TsvHeader);
		foreach (var result in results)
		{
			output.Output.WriteLine(ToTsvRow(result));
		}

		WriteSummary(output, results, unknownSites);
		return unknownSites == 0 ? 0 : 1;
	}

	private int RunPairs(string censusTsvPath, IReadOnlyList<TraceLine> lines, IAutoWrongCensusOutput output)
	{
		if (!File.Exists(censusTsvPath))
		{
			output.Error.WriteLine($"census tsv not found: {censusTsvPath}");
			return 1;
		}

		var rows = ReadCensusTsv(censusTsvPath, output);
		if (rows is null)
		{
			return 1;
		}

		var wanted = rows
			.Where(r => r.Blocker == "window" && (r.Route == "compound" || r.Route == "other"))
			.ToArray();

		var traceIndex = lines
			.Where(l => l.Atoms.Count > 0)
			.ToDictionary(l => (l.HoldoutId, l.LineIndex));

		output.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		var emitted = 0;
		foreach (var row in wanted)
		{
			if (!traceIndex.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				output.Error.WriteLine($"census row {row.HoldoutId}#{row.LineIndex} not found in the trace; skipped");
				continue;
			}

			var parsedNameHead = string.Join(' ', classifier.KeyHeadPhrase(_normalizerFor(line)));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(_normalizerFor(line, line.ExpectedDescriptions.FirstOrDefault())));
			output.Output.WriteLine($"{row.HoldoutId}\t{row.LineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		output.Error.WriteLine($"pairs: {emitted} of {wanted.Length} window compound/other rows emitted");
		return 0;
	}

	private static IReadOnlyList<string> _normalizerFor(TraceLine line) =>
		line.Atoms.FirstOrDefault()?.ParsedName is { Length: > 0 } name
			? FdcNormalizer.Default.NormalizeToTokens(name)
			: [];

	private static IReadOnlyList<string> _normalizerFor(TraceLine line, string? description) =>
		description is { Length: > 0 }
			? FdcNormalizer.Default.NormalizeToTokens(description)
			: [];

	private static void WriteSummary(IAutoWrongCensusOutput output, IReadOnlyList<ClassificationResult> results, int unknownSites)
	{
		var set = results.FirstOrDefault()?.Set ?? string.Empty;
		output.Error.WriteLine($"autoWrongCensus set={set} lines={results.Count}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			output.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		output.Error.WriteLine($"relation other: {other} of {results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).ToArray();
		output.Error.WriteLine(missing.Length == 0
			? "missing trace fields: none"
			: "missing trace fields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}")));

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToArray();
		output.Error.WriteLine($"override-site lines: {overrideLines.Length}, exact-overrides.json key hits: {overrideLines.Count(r => r.OverrideKey == "yes")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToArray();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			if (r.ParsedName.Length > 0 && !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), r.ParsedName))
			{
				reuseNameMismatch++;
			}
		}

		output.Error.WriteLine($"reuse-site lines: {reuseLines.Length} (production ShouldReuse(parsedName, parsedName) sanity: {reuseLines.Length - reuseNameMismatch} agree)");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToArray();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		output.Error.WriteLine($"row-choice-tier: {tierLines.Length} (key tier higher: {keyHigher}, accepted tier higher: {tierLines.Length - keyHigher})");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			output.Error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}

		if (unknownSites > 0)
		{
			output.Error.WriteLine($"unclassified (unknown atom path): {unknownSites}");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string ToTsvRow(ClassificationResult r) =>
		$"{Sanitize(r.HoldoutId)}\t{r.LineIndex.ToString(CultureInfo.InvariantCulture)}\t{Sanitize(r.Set)}\t{Sanitize(r.Relation)}\t{Sanitize(r.Site)}\t{Sanitize(r.OverrideKey)}\t{Sanitize(r.AcceptedTier)}\t{Sanitize(r.KeyTier)}\t{Sanitize(r.AcceptedState)}\t{Sanitize(r.KeyState)}\t{Sanitize(r.ParsedName)}\t{Sanitize(r.KeyHead)}\t{Sanitize(r.AcceptedDesc)}\t{Sanitize(r.KeyDesc)}\t{Sanitize(r.RawText)}";

	private static string Sanitize(string value)
	{
		if (value.Length == 0)
		{
			return string.Empty;
		}

		var builder = new StringBuilder(value.Length);
		foreach (var c in value)
		{
			builder.Append(c is '\t' or '\n' or '\r' ? ' ' : c);
		}

		return builder.ToString();
	}

	private static async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, IAutoWrongCensusOutput output, CancellationToken cancellationToken)
	{
		var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		try
		{
			await using var stream = File.OpenRead(path);
			await using var reader = new StreamReader(stream);
			while (true)
			{
				var line = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false);
				if (line is null)
				{
					break;
				}

				if (line.Trim().Length == 0)
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, options)
					?? throw new InvalidOperationException($"trace line in {path} deserialized to null"));
			}
		}
		catch (Exception ex) when (ex is IOException or JsonException or OperationCanceledException)
		{
			output.Error.WriteLine($"cannot read trace {path}: {ex.Message}");
			return null;
		}

		return lines;
	}

	private static IReadOnlyList<CensusRow>? ReadCensusTsv(string path, IAutoWrongCensusOutput output)
	{
		var rows = new List<CensusRow>();
		try
		{
			var allLines = File.ReadAllLines(path);
			if (allLines.Length == 0)
			{
				output.Error.WriteLine($"census tsv {path} is empty");
				return null;
			}

			var header = allLines[0].Split('\t');
			var column = new Dictionary<string, int>(StringComparer.Ordinal);
			for (var i = 0; i < header.Length; i++)
			{
				column[header[i]] = i;
			}

			foreach (var name in new[] { "holdoutId", "lineIndex", "blocker", "route" })
			{
				if (!column.ContainsKey(name))
				{
					output.Error.WriteLine($"census tsv {path} is missing column '{name}'");
					return null;
				}
			}

			for (var i = 1; i < allLines.Length; i++)
			{
				var cells = allLines[i].Split('\t');
				if (cells.Length < header.Length)
				{
					continue;
				}

				rows.Add(new CensusRow
				{
					HoldoutId = cells[column["holdoutId"]],
					LineIndex = int.Parse(cells[column["lineIndex"]], CultureInfo.InvariantCulture),
					Blocker = cells[column["blocker"]],
					Route = cells[column["route"]],
				});
			}
		}
		catch (Exception ex) when (ex is IOException or FormatException)
		{
			output.Error.WriteLine($"cannot read census tsv {path}: {ex.Message}");
			return null;
		}

		return rows;
	}
