{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads a HoldoutGate trace JSONL, refuses any set other than <c>debug</c>/<c>batch</c>
/// (D-029), classifies every <c>auto &amp;&amp; !correct</c> line, and writes the TSV to the output sink
/// and the relation × site summary to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers,
	FdcNormalizer normalizer) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		return _options.Command switch
		{
			CommandLineArgumentParser.CensusCommand => await RunCensusAsync(cancellationToken).ConfigureAwait(false),
			CommandLineArgumentParser.PairsCommand => await RunPairsAsync(cancellationToken).ConfigureAwait(false),
			_ => Fail("unusable arguments; run with --help"),
		};
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace set '{refused}' is not debug or batch (D-029)");
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		foreach (var line in autoWrong)
		{
			cancellationToken.ThrowIfCancellationRequested();
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				return Fail($"unknown atom path '{FirstAtomPath(line)}' on {line.HoldoutId}#{line.LineIndex}; refusing to emit a partial census");
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteCensusSummary(lines, results);
		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = RefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace set '{refused}' is not debug or batch (D-029)");
		}

		if (!File.Exists(_options.CensusTsvPath))
		{
			return Fail($"census TSV not found at '{_options.CensusTsvPath}'");
		}

		var census = ReadCensusTsv(_options.CensusTsvPath);
		if (census is null)
		{
			return Fail($"census TSV '{_options.CensusTsvPath}' is missing the holdoutId/lineIndex/blocker/route columns");
		}

		var byLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var matched = 0;
		var unmatched = 0;
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var row in census)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!byLine.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			matched++;
			var parsedNameHead = string.Join(' ', SingularTokens(normalizer.NormalizeToTokens(FirstAtomParsedName(line))));
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(normalizer.NormalizeToTokens(First(line.ExpectedDescriptions))));
			writers.Output.WriteLine($"{Sanitize(row.HoldoutId)}\t{row.LineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
		}

		writers.Error.WriteLine($"pairs: census rows={census.Count} matched={matched} unmatched={unmatched}");
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteCensusSummary(IReadOnlyList<TraceLine> lines, IReadOnlyList<ClassificationResult> results)
	{
		var set = lines.Count > 0 ? lines[0].Set : string.Empty;
		writers.Error.WriteLine($"autoWrongCensus set={set} traced={lines.Count} autoWrong={results.Count}");

		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation).ThenBy(g => g.Key.Site))
		{
			writers.Error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key);
		writers.Error.WriteLine(missing.Any()
			? "missingFields: " + string.Join(", ", missing.Select(g => $"{g.Key}={g.Count()}"))
			: "missingFields: none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		writers.Error.WriteLine($"overrideKey yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			var linked = FirstAtomLinkedId(r);
			if (linked is not null && !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(r.ParsedName), linked))
			{
				reuseNameMismatch++;
			}
		}

		writers.Error.WriteLine($"reuse lines={reuseLines.Count} shouldReuse(parsedName,linkedIngredientId)=false:{reuseNameMismatch}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		writers.Error.WriteLine($"row-choice-tier keyHigher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} acceptedHigher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(' ', r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		if (!File.Exists(path))
		{
			return Fail($"trace not found at '{path}'");
		}

		var lines = new List<TraceLine>();
		await foreach (var line in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
		{
			if (line.Length == 0)
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (Exception ex) when (ex is JsonException or InvalidOperationException)
			{
				return Fail($"trace '{path}' has an unparseable line: {ex.Message}");
			}
		}

		return lines;
	}

	private static string? RefusedSet(IReadOnlyList<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.Ordinal) && !line.Set.Equals("batch", StringComparison.Ordinal))
			{
				return line.Set;
			}
		}

		return null;
	}

	private static (string HoldoutId, int LineIndex, string Blocker, string Route)? ReadCensusTsv(string path)
	{
		var header = File.ReadLines(path).FirstOrDefault()?.Split('\t') ?? [];
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf.TryAdd(header[i], i);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				return null;
			}
		}

		var rows = new List<(string, int, string, string)>();
		var first = true;
		foreach (var line in File.ReadLines(path))
		{
			if (first)
			{
				first = false;
				continue;
			}

			var cells = line.Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			var blocker = cells[indexOf["blocker"]];
			var route = cells[indexOf["route"]];
			if (!blocker.Equals("window", StringComparison.Ordinal) || (route != "compound" && route != "other"))
			{
				continue;
			}

			rows.Add((cells[indexOf["holdoutId"]], int.Parse(cells[indexOf["lineIndex"]]), blocker, route));
		}

		return rows;
	}

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private static string FirstAtomPath(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static string FirstAtomParsedName(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].ParsedName : string.Empty;

	private static string? FirstAtomLinkedId(ClassificationResult result) =>
		result.ParsedName.Length == 0 ? null : null;

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static IReadOnlyList<string> SingularTokens(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), t => IngredientLineResolver.SingularizeToken(t));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private int Fail(string message)
	{
		writers.Error.WriteLine($"AutoWrongCensus: {message}");
		return 1;
	}
}
